// Map the Artificial Analysis payload onto trackai's model shape.
// AA has changed field names before, so read defensively and skip anything
// we can't confidently identify rather than writing junk rows.
const payload = $input.first().json;
const rows = payload.data ?? payload.models ?? payload ?? [];

const slugify = (s) =>
  String(s).toLowerCase().trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 200);

const num = (v) => (v === null || v === undefined || v === '' || Number.isNaN(Number(v)) ? null : Number(v));

const models = [];
for (const r of Array.isArray(rows) ? rows : []) {
  const name = r.name ?? r.model_name ?? r.slug;
  if (!name) continue;

  const provider = r.model_creator?.name ?? r.creator?.name ?? r.creator ?? r.provider;
  if (!provider) continue;

  const released = r.release_date ?? r.released_at ?? null;
  const ev = r.evaluations ?? r.metrics ?? r;

  models.push({
    name: String(name).slice(0, 200),
    slug: slugify(r.slug ?? name),
    provider: String(provider).slice(0, 120),
    status: 'released',
    actualDate: released ? String(released).slice(0, 10) : null,
    intelligenceIndex: num(ev.artificial_analysis_intelligence_index ?? ev.intelligence_index),
    codingIndex: num(ev.artificial_analysis_coding_index ?? ev.coding_index),
    pricePerMtok: num(r.pricing?.price_1m_blended_3_to_1 ?? r.pricing?.price_1m_output_tokens),
    speedTps: num(r.median_output_tokens_per_second ?? r.output_tokens_per_second),
    benchmarkSource: 'Artificial Analysis',
  });
}

if (!models.length) {
  throw new Error('No models parsed from Artificial Analysis — response shape may have changed. Inspect the previous node output before letting this run again.');
}

return [{ json: { models } }];
